# Integer square root — binary search on answer
def isqrt(n):
    if n < 0:
        return -1
    lo, hi = 0, n
    while lo <= hi:
        mid = (lo + hi) // 2
        if mid * mid == n:
            return mid
        elif mid * mid < n:
            lo = mid + 1
        else:
            hi = mid - 1
    return hi   # floor of sqrt

