# Minimum pages — allocate books to students
# Each student gets contiguous books, minimise max pages any student reads
def can_allocate(pages, students, max_pages):
    count, current = 1, 0
    for p in pages:
        if p > max_pages:
            return False
        if current + p > max_pages:
            count += 1
            current = p
        else:
            current += p
    return count <= students

def min_pages(pages, students):
    lo, hi = max(pages), sum(pages)
    result = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        if can_allocate(pages, students, mid):
            result = mid
            hi = mid - 1   # try smaller
        else:
            lo = mid + 1
    return result

