import math

# Jump Search — O(√n)
def jump_search(arr, target):
    n    = len(arr)
    step = int(math.sqrt(n))
    prev = 0
    # Jump forward in blocks
    while prev < n and arr[min(step, n)-1] < target:
        prev  = step
        step += int(math.sqrt(n))
        if prev >= n:
            return -1
    # Linear search in the identified block
    for i in range(prev, min(step, n)):
        if arr[i] == target:
            return i
    return -1

