# Iterative factorial using explicit stack
def factorial_iterative(n):
    result = 1
    while n > 1:
        result *= n
        n -= 1
    return result

# Simulate recursive DFS with explicit stack
def dfs_iterative(graph, start):
    visited = set()
    stack   = [start]          # explicit stack replaces call stack
    order   = []
    while stack:
        node = stack.pop()     # LIFO — mimics recursion
        if node not in visited:
            visited.add(node)
            order.append(node)
            for neighbour in reversed(graph[node]):
                if neighbour not in visited:
                    stack.append(neighbour)
    return order

