# [[], [1], [1,2], [1,2,3], [1,3], [2], [2,3], [3]]

# N-Queens — place N queens on NxN board, no two attack each other
def n_queens(n):
    solutions = []
    board = [-1] * n   # board[i] = column of queen in row i

    def is_safe(row, col):
        for r in range(row):
            c = board[r]
            if c == col or abs(c - col) == abs(r - row):
                return False   # same column or diagonal
        return True

    def backtrack(row):
        if row == n:            # all queens placed
            solutions.append(board[:])
            return
        for col in range(n):
            if is_safe(row, col):
                board[row] = col         # place queen
                backtrack(row + 1)       # next row
                board[row] = -1          # remove queen (backtrack)

    backtrack(0)
    return len(solutions)

print(n_queens(4))   # 2
print(n_queens(8))   # 92

