# Coin Change — minimum coins to make amount
# State: min_coins(amount)
# Recurrence: min_coins(a) = 1 + min(min_coins(a - c) for c in coins if c <= a)
@lru_cache(maxsize=None)
def min_coins(amount, coins):
    if amount == 0: return 0          # base case
    if amount < 0:  return float('inf')
    return 1 + min(min_coins(amount - c, coins)
                   for c in coins if c <= amount)

