# Unique paths in m×n grid (only right or down moves)
@lru_cache(maxsize=None)
def unique_paths(m, n):
    if m == 1 or n == 1: return 1   # base: only one path along edge
    return unique_paths(m-1, n) + unique_paths(m, n-1)

