# Longest Common Subsequence (LCS)
@lru_cache(maxsize=None)
def lcs(s1, s2, i=0, j=0):
    if i == len(s1) or j == len(s2):   # base case
        return 0
    if s1[i] == s2[j]:                  # chars match
        return 1 + lcs(s1, s2, i+1, j+1)
    return max(lcs(s1, s2, i+1, j),    # skip s1[i]
               lcs(s1, s2, i, j+1))    # skip s2[j]

