# BFS Shortest Path — returns distance from source to all vertices
def bfs_shortest(graph, start):
    dist    = {start: 0}
    queue   = deque([start])
    while queue:
        node = queue.popleft()
        for nb in graph[node]:
            if nb not in dist:
                dist[nb] = dist[node] + 1
                queue.append(nb)
    return dist

print(bfs_shortest(graph, 0))  # {0:0, 1:1, 2:1, 3:2, 4:2}

# BFS Path Reconstruction
def bfs_path(graph, start, end):
    parent = {start: None}
    queue  = deque([start])
    while queue:
        node = queue.popleft()
        if node == end:
            break
        for nb in graph[node]:
            if nb not in parent:
                parent[nb] = node
                queue.append(nb)
    if end not in parent: return []
    path = []
    node = end
    while node is not None:
        path.append(node)
        node = parent[node]
    return path[::-1]

print(bfs_path(graph, 0, 3))   # [0, 1, 3]

# DFS Recursive
def dfs_recursive(graph, node, visited=None, order=None):
    if visited is None: visited = set()
    if order   is None: order   = []
    visited.add(node)
    order.append(node)
    for nb in graph[node]:
        if nb not in visited:
            dfs_recursive(graph, nb, visited, order)
    return order

