# DFS Iterative (explicit stack)
def dfs_iterative(graph, start):
    visited = set()
    stack   = [start]
    order   = []
    while stack:
        node = stack.pop()        # LIFO — pop from top
        if node not in visited:
            visited.add(node)
            order.append(node)
            for nb in reversed(graph[node]):
                if nb not in visited:
                    stack.append(nb)
    return order

# Cycle Detection in Directed Graph
def has_cycle_directed(graph):
    WHITE, GREY, BLACK = 0, 1, 2
    colour = {v: WHITE for v in graph}

    def dfs(v):
        colour[v] = GREY          # mark as in-progress
        for nb in graph.get(v, []):
            if colour[nb] == GREY:  # back edge = cycle!
                return True
            if colour[nb] == WHITE and dfs(nb):
                return True
        colour[v] = BLACK         # fully processed
        return False

    return any(dfs(v) for v in graph if colour[v] == WHITE)

