# Topological Sort using DFS (for DAGs)
def topological_sort(graph):
    visited = set()
    order   = []

    def dfs(v):
        visited.add(v)
        for nb in graph.get(v, []):
            if nb not in visited:
                dfs(nb)
        order.append(v)           # add AFTER visiting all descendants

    for v in graph:
        if v not in visited:
            dfs(v)
    return order[::-1]            # reverse for topological order

