# Count Connected Components
def count_components(n, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited    = set()
    components = 0

    def dfs(v):
        visited.add(v)
        for nb in graph[v]:
            if nb not in visited:
                dfs(nb)

    for v in range(n):
        if v not in visited:
            dfs(v)
            components += 1
    return components

