# Iterative Inorder — using explicit stack
def inorder_iterative(root):
    result, stack = [], []
    curr = root
    while curr or stack:
        while curr:              # go as left as possible
            stack.append(curr)
            curr = curr.left
        curr = stack.pop()       # visit node
        result.append(curr.val)
        curr = curr.right        # move to right subtree
    return result

# Iterative Preorder
def preorder_iterative(root):
    if not root: return []
    result, stack = [], [root]
    while stack:
        node = stack.pop()
        result.append(node.val)
        if node.right: stack.append(node.right)  # right first
        if node.left:  stack.append(node.left)   # left second (processed first)
    return result

# Zigzag Level Order (alternating left-right)
def zigzag_level_order(root):
    if not root: return []
    result, queue = [], deque([root])
    left_to_right = True
    while queue:
        level = deque()
        for _ in range(len(queue)):
            node = queue.popleft()
            if left_to_right: level.append(node.val)
            else:             level.appendleft(node.val)
            if node.left:  queue.append(node.left)
            if node.right: queue.append(node.right)
        result.append(list(level))
        left_to_right = not left_to_right
    return result

